input.dsl:
workspace "Web Shop" "A multi-file Structurizr workspace using the team's !include and !docs conventions." {

    model {

        customer = person "Customer" {
            "A customer who browses products and places orders on the web shop."
            tags "Customer"
        }

        support = person "Support Agent" {
            "A support agent who helps customers and manages orders."
            tags "Support"
        }

        webShop = softwareSystem "Web Shop" {
            "An online store where customers browse products and place orders."
            tags "Web"
        }

        crm = softwareSystem "CRM" {
            "An external customer relationship management system."
            tags "External"
        }

        paymentGateway = softwareSystem "Payment Gateway" {
            "An external payment processing service."
            tags "External"
        }

        webShop {
            storefront = container "Storefront" "React" {
                "The customer-facing web application for browsing products and checking out."
                tags "Web"
            }

            api = container "API" "Node.js" {
                "The REST API that serves product and order data."
                tags "Api"
            }

            orderService = container "Order Service" "Java" {
                "Processes and manages customer orders."
                tags "Service"
            }

            database = container "Database" "PostgreSQL" {
                "Stores products, orders, and customer data."
                tags "Database"
            }

            storefront -> api "Browses products and places orders"
            api -> orderService "Creates and updates orders"
            orderService -> database "Persists order data"
            api -> paymentGateway "Charges customers"
            orderService -> crm "Syncs customer data"
        }

        webShop {
            orderService {
                orderValidator = component "Order Validator" {
                    "Validates order data before processing."
                }

                orderRepository = component "Order Repository" {
                    "Provides data access for orders."
                }

                orderValidator -> orderRepository "Loads and saves orders"
            }
        }
    }

    views {
        systemLandscape "systemLandscape" {
            include *
            autoLayout
            * -> * $tags != "Internal"

            styles {
                person {
                    background #08427B
                    color #FFFFFF
                }
            }
        }

        systemContext webShop "webShopContext" {
            include *
            autoLayout
            * -> * $tags != "Internal"
        }

        container webShop "webShopContainers" {
            include *
            autoLayout
            * -> * $tags != "Internal"
        }

        component orderService "orderServiceComponents" {
            include *
            autoLayout
        }
    }
}

