input.dsl:
workspace "Web Shop" "A multi-file Structurizr workspace using the team's !include and !docs conventions." {

    model {

        customer = person "Customer" {
            description "A customer who browses products and places orders on the web shop."
            tags "Customer"
        }

        support = person "Support Agent" {
            description "A support agent who helps customers and manages orders."
            tags "Support"
        }

        crm = softwareSystem "CRM" {
            description "An external customer relationship management system."
            tags "External"
        }

        paymentGateway = softwareSystem "Payment Gateway" {
            description "An external payment processing service."
            tags "External"
        }

        webShop = softwareSystem "Web Shop" {
            description "An online store where customers browse products and place orders."
            tags "Web"

            storefront = container "Storefront" "React" {
                description "The customer-facing web application for browsing products and checking out."
                tags "Web"
            }

            api = container "API" "Node.js" {
                description "The REST API that serves product and order data."
                tags "Api"
            }

            orderService = container "Order Service" "Java" {
                description "Processes and manages customer orders."
                tags "Service"

                orderValidator = component "Order Validator" {
                    description "Validates order data before processing."
                }

                orderRepository = component "Order Repository" {
                    description "Provides data access for orders."
                }

                orderValidator -> orderRepository "Loads and saves orders"
            }

            database = container "Database" "PostgreSQL" {
                description "Stores products, orders, and customer data."
                tags "Database"
            }

            customer -> storefront "Browses and purchases"
            support -> api "Manages orders"
            storefront -> api "Makes requests"
            api -> orderService "Creates and updates orders"
            orderService -> database "Persists order data"
            api -> paymentGateway "Charges customers"
            orderService -> crm "Syncs customer data"
        }
    }

    views {
        systemLandscape "systemLandscape" {
            include *
            autoLayout
        }

        systemContext webShop "webShopContext" {
            include *
            autoLayout
        }

        container webShop "webShopContainers" {
            include *
            autoLayout
        }

        component orderService "orderServiceComponents" {
            include *
            autoLayout
        }
    }
}

